<div class="page-head"><div><span class="eyebrow blue">ERWEITERUNGEN</span><h1>Pluginmanager</h1><p>Erweitere die Administration mit unabhängigen Modulen.</p></div><button class="primary" disabled>Plugin hinzufügen</button></div>
<div class="stat-row"><div><span>Installiert</span><strong><?= count($plugins) ?></strong></div><div><span>Aktiv</span><strong><?= count(array_filter($plugins, fn($p) => $p['active'])) ?></strong></div><div><span>Updates</span><strong>0</strong></div></div>
<section class="panel"><div class="panel-head"><div><h2>Installierte Plugins</h2><p>Aktiviere, deaktiviere und konfiguriere deine Erweiterungen.</p></div><input class="search" type="search" placeholder="Plugins durchsuchen …"></div><div class="plugin-list">
<?php foreach ($plugins as $plugin): ?><article class="plugin-item"><div class="plugin-symbol"><?= htmlspecialchars(strtoupper(substr($plugin['label'],0,1))) ?></div><div class="plugin-info"><h3><?= htmlspecialchars($plugin['label']) ?> <?php if ($plugin['core']): ?><span class="badge">CORE</span><?php endif ?></h3><p><?= htmlspecialchars($plugin['description']) ?></p><small>Version <?= htmlspecialchars($plugin['version']) ?></small></div><span class="state <?= $plugin['active'] ? 'on' : '' ?>"><?= $plugin['active'] ? 'Aktiv' : 'Inaktiv' ?></span><?php if (!$plugin['core']): ?><form method="post"><input type="hidden" name="_token" value="<?= htmlspecialchars($token) ?>"><input type="hidden" name="plugin" value="<?= htmlspecialchars($plugin['name']) ?>"><button class="secondary"><?= $plugin['active'] ? 'Deaktivieren' : 'Aktivieren' ?></button></form><?php endif ?></article><?php endforeach ?>
</div></section>
